<style>.evt-wrap .hero,.evt-wrap .cardx{background:rgba(17,24,39,.94);border:1px solid rgba(255,255,255,.08);border-radius:22px;box-shadow:0 18px 40px rgba(0,0,0,.24)}.evt-wrap .hero{padding:24px;margin-bottom:22px;background:linear-gradient(135deg,rgba(16,185,129,.14),rgba(17,24,39,.75))}.evt-wrap .cardx{padding:20px}.evt-wrap .table{--bs-table-bg:transparent;--bs-table-color:#e5e7eb;--bs-table-border-color:rgba(255,255,255,.07)}.evt-wrap .muted{color:#9ca3af}</style>
<div class="container-fluid mt-4 evt-wrap"><div class="hero d-flex justify-content-between gap-3 flex-wrap"><div><h2>📡 Event Center</h2><div class="muted">Historial central de operaciones, automatizaciones, errores y cambios de estado.</div></div><button class="btn btn-outline-light" onclick="loadEvents()">↻ Refrescar</button></div><div class="cardx"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Nivel</th><th>Tipo</th><th>Evento</th></tr></thead><tbody id="eventsBody"><tr><td colspan="4">Cargando…</td></tr></tbody></table></div></div></div>
<script>(function(){const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));window.loadEvents=function(){fetch('api.php?action=events_list',{credentials:'same-origin'}).then(r=>r.json()).then(j=>{const b=document.getElementById('eventsBody');const items=(j.items||[]).slice().reverse();if(!items.length){b.innerHTML='<tr><td colspan="4">📭 Sin eventos</td></tr>';return;}b.innerHTML=items.map(e=>`<tr><td>${esc(e.date)}</td><td><span class="badge bg-${e.level==='error'?'danger':e.level==='success'?'success':e.level==='warning'?'warning':'secondary'}">${esc(e.level)}</span></td><td>${esc(e.type)}</td><td>${esc(e.message)}</td></tr>`).join('');});};loadEvents();})();</script>
